function blocks(
  id: string,
  texts: string[],
): FunctionalParticipation["execution_blocks"] {
  return texts.map((text, index) => ({
    kind: "execution_block" as const,
    id: `${id}-b${index + 1}`,
    order: index + 1,
    text,
  }));
}

